
"""Interactive map of Norwegian electricity price areas."""

import json
from pathlib import Path

import streamlit as st
import pydeck as pdk

import copy
import pandas as pd
import requests

st.title("Interactive Map", icon=":material/map:")
st.write(
    "Explore Norwegian electricity price areas and their "
    "geographic boundaries."
)

# Locate the GeoJSON file generated by prepare_geojson.py.
ROOT = Path(__file__).resolve().parents[2]
GEOJSON_PATH = ROOT / "data" / "geojson" / "price_areas.geojson"


@st.cache_data
def load_geojson(path):
    """Read geographic boundaries without repeating file operations."""
    with open(path, encoding="utf-8") as file:
        return json.load(file)


# Load the five electricity price-area polygons.
price_areas = load_geojson(str(GEOJSON_PATH))

# Remember the selected region across Streamlit pages.
if "map_selected_region" not in st.session_state:
    st.session_state["map_selected_region"] = None


@st.cache_data(ttl=3600)
def load_reservoir_filling():
    """Download weekly filling measurements for electricity areas."""

    url = (
        "https://biapi.nve.no/magasinstatistikk/api/"
        "Magasinstatistikk/HentOffentligData"
    )

    response = requests.get(url, timeout=60)
    response.raise_for_status()

    data = pd.DataFrame(response.json())

    # Keep electricity-area measurements only.
    data = data[data["omrType"] == "EL"].copy()
    data["date"] = pd.to_datetime(data["dato_Id"])
    data["omrnr"] = pd.to_numeric(data["omrnr"])
    data["fyllingsgrad"] = pd.to_numeric(data["fyllingsgrad"])

    return data


try:
    reservoir_data = load_reservoir_filling()
except (requests.RequestException, ValueError) as error:
    st.error(f"Could not load reservoir statistics: {error}")
    st.stop()

# Let the user choose an actual reporting date from the dataset.
available_dates = sorted(
    reservoir_data["date"].dropna().unique(),
    reverse=True
)

color_mode = st.radio(
    "Colour areas by",
    ["Reservoir filling", "Electricity price area"],
    horizontal=True
)

selected_date = st.selectbox(
    "Reservoir reporting week",
    options=available_dates,
    format_func=lambda d: pd.Timestamp(d).strftime("%d %B %Y")
)

# Get filling percentages for the selected week.
weekly_data = reservoir_data[
    reservoir_data["date"] == selected_date
]

filling_by_area = (
    weekly_data.set_index("omrnr")["fyllingsgrad"].to_dict()
)


def filling_color(value):
    """Return an RGBA colour based on reservoir filling (0–1)."""

    return [
        int(235 - 185 * value),  # Red decreases
        int(110 + 55 * value),   # Green increases
        int(65 + 155 * value),   # Blue increases
        140                      # Transparency
    ]


# Copy the original boundaries so the cached data stays unchanged.
colored_areas = copy.deepcopy(price_areas)

# Distinct colours for identifying electricity price areas.
area_colors = {
    "NO1": [70, 130, 200, 140],
    "NO2": [65, 170, 130, 140],
    "NO3": [180, 115, 190, 140],
    "NO4": [230, 160, 65, 140],
    "NO5": [90, 175, 190, 140]
}


for feature in colored_areas["features"]:
    region = feature["properties"]["region"]
    area_number = int(region.replace("NO", ""))

    filling = filling_by_area.get(area_number)

    if color_mode == "Electricity price area":
        # Each price area receives its own identifying colour.
        feature["properties"]["fill_color"] = area_colors[region]
        feature["properties"]["filling_label"] = "Not displayed"

    elif filling is not None and pd.notna(filling):
        # Colour by the selected week's reservoir filling.
        feature["properties"]["fill_color"] = filling_color(filling)
        feature["properties"]["filling_label"] = f"{filling:.1%}"

    else:
        # Grey indicates missing reservoir measurements.
        feature["properties"]["fill_color"] = [150, 150, 150, 100]
        feature["properties"]["filling_label"] = "No data"


# Draw semi-transparent polygons with visible outlines.
layer = pdk.Layer(
    "GeoJsonLayer",
    data=colored_areas,
    id="price-areas",
    filled=True,
    stroked=True,
    pickable=True,
    auto_highlight=True,
    get_fill_color="properties.fill_color",
    get_line_color=[40, 70, 110, 255],
    line_width_min_pixels=2,
)

# Display the normal price-area polygons.
layers = [layer]

# Draw a thicker outline around the selected area.
selected_region = st.session_state["map_selected_region"]

if selected_region is not None:
    selected_features = [
        feature for feature in price_areas["features"]
        if feature["properties"]["region"] == selected_region
    ]

    if selected_features:
        highlight_layer = pdk.Layer(
            "GeoJsonLayer",
            data={
                "type": "FeatureCollection",
                "features": selected_features
            },
            id="selected-area-outline",
            filled=False,
            stroked=True,
            pickable=False,
            get_line_color=[255, 160, 50, 255],
            line_width_min_pixels=5
        )

        layers.append(highlight_layer)

# Position the map to show mainland Norway.
view = pdk.ViewState(
    latitude=64.5,
    longitude=14.0,
    zoom=3.7,
    pitch=0,
)

deck = pdk.Deck(
    layers=layers,
    initial_view_state=view,
    map_style=None,
    tooltip={"text": "Electricity area: {region}\nReservoir filling: {filling_label}"},
)

# Allow users to select one polygon at a time.
event = st.pydeck_chart(
    deck,
    use_container_width=True,
    on_select="rerun",
    selection_mode="single-object",
    key="price_area_map"
)

# Get the selected polygon's index in the GeoJSON feature list.
selected_indices = event.selection.indices.get("price-areas", [])

if selected_indices:
    selected_index = selected_indices[0]
    region = price_areas["features"][selected_index]["properties"]["region"]

    # Save changes and redraw the map with the new highlight.
    if region != st.session_state["map_selected_region"]:
        st.session_state["map_selected_region"] = region
        st.rerun()

# Show the current selection underneath the map.
if st.session_state["map_selected_region"]:
    st.success(
        f"Selected electricity area: {st.session_state['map_selected_region']}"
    )
else:
    st.info("Click an electricity area on the map to select it.")

if color_mode == "Reservoir filling":
    st.caption(
        "Colour scale: orange indicates lower reservoir filling, "
        "while blue indicates higher filling."
    )
else:
    st.caption(
        "Each colour identifies a separate electricity price area. "
        "Hover over a polygon to see its name."
    )

st.caption(
    "Electricity price-area boundaries from NVE Atlas. "
    "Hover over an area to see its identifier."
)

